// Tool: search_menu
// Input: { query: string }
const query = $input.item.json.query?.toLowerCase() || '';
const menuJson = JSON.parse($('Extrai Campos').item.json.menu_json || '[]');

if (!query) {
  return { json: { products: menuJson.slice(0, 10), message: 'Mostrando os 10 primeiros produtos' } };
}

const results = menuJson.filter(product => 
  product.name?.toLowerCase().includes(query) || 
  product.description?.toLowerCase().includes(query) ||
  product.category?.toLowerCase().includes(query)
);

return { 
  json: { 
    products: results.slice(0, 5),
    found: results.length,
    message: results.length > 0 
      ? `Encontrei ${results.length} produto(s) para "${query}"` 
      : `Nenhum produto encontrado para "${query}"`
  } 
};

