// Tool: send_product_photo
// Input: { product_id: string, product_name: string, product_price: number, image_url: string }
const productId = $input.item.json.product_id;
const productName = $input.item.json.product_name;
const productPrice = $input.item.json.product_price;
const imageUrl = $input.item.json.image_url;

const instanceName = $('Extrai Campos').item.json.instance_name;
const remoteJid = $('Extrai Campos').item.json.remote_jid;
const evolutionApiUrl = $env.EVOLUTION_API_URL;
const evolutionApiKey = $env.EVOLUTION_API_KEY;

if (!imageUrl) {
  return { json: { success: false, message: 'Produto sem imagem disponível' } };
}

const caption = `📦 *${productName}*\n💰 R$ ${productPrice?.toFixed(2) || '0.00'}\n\nDigite o número do produto para adicionar ao carrinho!`;

try {
  const response = await fetch(`${evolutionApiUrl}/message/sendMedia/${instanceName}`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'apikey': evolutionApiKey
    },
    body: JSON.stringify({
      number: remoteJid.replace('@s.whatsapp.net', ''),
      mediatype: 'image',
      media: imageUrl,
      caption: caption
    })
  });

  const result = await response.json();
  return { json: { success: true, message: `Foto de ${productName} enviada!`, result } };
} catch (error) {
  return { json: { success: false, message: `Erro ao enviar foto: ${error.message}` } };
}

