// Tool: add_to_cart
// Input: { product_id: string, product_name: string, quantity: number, unit_price: number, observations?: string }
const Redis = require('ioredis');
const redis = new Redis($env.REDIS_URL);

const productId = $input.item.json.product_id;
const productName = $input.item.json.product_name;
const quantity = parseInt($input.item.json.quantity) || 1;
const unitPrice = parseFloat($input.item.json.unit_price) || 0;
const observations = $input.item.json.observations || '';
const sessionKey = $('Extrai Campos').item.json.session_key;
const cartKey = `vilafood:cart:${sessionKey}`;

try {
  // Busca carrinho atual
  let cartData = await redis.get(cartKey);
  let cart = cartData ? JSON.parse(cartData) : { items: [], total: 0 };

  // Verifica se produto já existe
  const existingIndex = cart.items.findIndex(item => item.product_id === productId);

  if (existingIndex >= 0) {
    cart.items[existingIndex].quantity += quantity;
    cart.items[existingIndex].subtotal = cart.items[existingIndex].quantity * unitPrice;
  } else {
    cart.items.push({
      product_id: productId,
      product_name: productName,
      quantity: quantity,
      unit_price: unitPrice,
      subtotal: quantity * unitPrice,
      observations: observations
    });
  }

  // Recalcula total
  cart.total = cart.items.reduce((sum, item) => sum + item.subtotal, 0);
  cart.updated_at = new Date().toISOString();

  // Salva com TTL de 2 horas
  await redis.set(cartKey, JSON.stringify(cart), 'EX', 7200);
  await redis.quit();

  return { 
    json: { 
      success: true, 
      message: `✅ ${quantity}x ${productName} adicionado ao carrinho!`,
      cart_items: cart.items.length,
      cart_total: cart.total.toFixed(2)
    } 
  };
} catch (error) {
  await redis.quit();
  return { json: { success: false, message: `Erro ao adicionar: ${error.message}` } };
}

