// Tool: create_order_pix
// Input: { delivery_address: string, delivery_type?: string, observations?: string }
const Redis = require('ioredis');
const redis = new Redis($env.REDIS_URL);

const deliveryAddress = $input.item.json.delivery_address;
const deliveryType = $input.item.json.delivery_type || 'delivery';
const observations = $input.item.json.observations || '';

const sessionKey = $('Extrai Campos').item.json.session_key;
const cartKey = `vilafood:cart:${sessionKey}`;
const establishmentId = $('Extrai Campos').item.json.establishment_id;
const phone = $('Extrai Campos').item.json.phone;
const customerName = $('Extrai Campos').item.json.push_name;
const mercadoPagoToken = $('Extrai Campos').item.json.mercado_pago_token;
const supabaseUrl = $env.SUPABASE_URL;
const supabaseKey = $env.SUPABASE_SERVICE_ROLE_KEY;

try {
  // Busca carrinho
  let cartData = await redis.get(cartKey);
  if (!cartData) {
    await redis.quit();
    return { json: { success: false, message: '❌ Carrinho vazio! Adicione produtos primeiro.' } };
  }

  const cart = JSON.parse(cartData);
  if (!cart.items?.length) {
    await redis.quit();
    return { json: { success: false, message: '❌ Carrinho vazio!' } };
  }

  // Chama Edge Function mercadopago-pix
  const pixResponse = await fetch(`${supabaseUrl}/functions/v1/mercadopago-pix`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${supabaseKey}`
    },
    body: JSON.stringify({
      establishment_id: establishmentId,
      amount: cart.total,
      customer_name: customerName,
      customer_phone: phone,
      items: cart.items,
      delivery_address: deliveryAddress,
      delivery_type: deliveryType,
      observations: observations
    })
  });

  const pixResult = await pixResponse.json();

  if (pixResult.error) {
    await redis.quit();
    return { json: { success: false, message: `❌ Erro no PIX: ${pixResult.error}` } };
  }

  // Limpa carrinho após criar pedido
  await redis.del(cartKey);
  await redis.quit();

  return { 
    json: { 
      success: true, 
      message: `✅ Pedido #${pixResult.order_id?.slice(0, 8)} criado!\n\n💰 Total: R$ ${cart.total.toFixed(2)}\n\n📱 Use o código PIX abaixo para pagar:\n\n${pixResult.pix_code}\n\nOu escaneie o QR Code que enviarei em seguida.`,
      order_id: pixResult.order_id,
      pix_code: pixResult.pix_code,
      qr_code_base64: pixResult.qr_code_base64,
      total: cart.total
    } 
  };
} catch (error) {
  await redis.quit();
  return { json: { success: false, message: `❌ Erro ao criar pedido: ${error.message}` } };
}

