// Tool: save_customer
// Input: { name?: string, address?: string, neighborhood?: string, city?: string, zip_code?: string }
const customerName = $input.item.json.name || $('Extrai Campos').item.json.push_name;
const address = $input.item.json.address;
const neighborhood = $input.item.json.neighborhood;
const city = $input.item.json.city;
const zipCode = $input.item.json.zip_code;

const phone = $('Extrai Campos').item.json.phone;
const establishmentId = $('Extrai Campos').item.json.establishment_id;
const supabaseUrl = $env.SUPABASE_URL;
const supabaseKey = $env.SUPABASE_SERVICE_ROLE_KEY;

try {
  const addressData = {
    street: address,
    neighborhood: neighborhood,
    city: city,
    zip_code: zipCode
  };

  // Upsert no Supabase
  const response = await fetch(`${supabaseUrl}/rest/v1/customers?phone=eq.${phone}&establishment_id=eq.${establishmentId}`, {
    method: 'GET',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${supabaseKey}`,
      'apikey': supabaseKey
    }
  });

  const existing = await response.json();

  let result;
  if (existing && existing.length > 0) {
    // Update
    result = await fetch(`${supabaseUrl}/rest/v1/customers?id=eq.${existing[0].id}`, {
      method: 'PATCH',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${supabaseKey}`,
        'apikey': supabaseKey,
        'Prefer': 'return=representation'
      },
      body: JSON.stringify({
        name: customerName,
        default_address: addressData,
        updated_at: new Date().toISOString()
      })
    });
  } else {
    // Insert
    result = await fetch(`${supabaseUrl}/rest/v1/customers`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${supabaseKey}`,
        'apikey': supabaseKey,
        'Prefer': 'return=representation'
      },
      body: JSON.stringify({
        phone: phone,
        name: customerName,
        establishment_id: establishmentId,
        default_address: addressData
      })
    });
  }

  return { 
    json: { 
      success: true, 
      message: `✅ Dados salvos! ${customerName}, ${address}${neighborhood ? ', ' + neighborhood : ''}` 
    } 
  };
} catch (error) {
  return { json: { success: false, message: `Erro ao salvar: ${error.message}` } };
}

// Tool: view_cart
const Redis = require('ioredis');
const redis = new Redis($env.REDIS_URL);

const sessionKey = $('Extrai Campos').item.json.session_key;
const cartKey = `vilafood:cart:${sessionKey}`;

try {
  let cartData = await redis.get(cartKey);
  await redis.quit();

  if (!cartData) {
    return { json: { success: true, message: '🛒 Carrinho vazio!', items: [], total: 0 } };
  }

  const cart = JSON.parse(cartData);

  if (!cart.items?.length) {
    return { json: { success: true, message: '🛒 Carrinho vazio!', items: [], total: 0 } };
  }

  let itemsList = cart.items.map((item, idx) => 
    `${idx + 1}. ${item.quantity}x ${item.product_name} - R$ ${item.subtotal.toFixed(2)}`
  ).join('\n');

  return { 
    json: { 
      success: true, 
      message: `🛒 *Seu Carrinho:*\n\n${itemsList}\n\n💰 *Total: R$ ${cart.total.toFixed(2)}*`,
      items: cart.items,
      total: cart.total
    } 
  };
} catch (error) {
  await redis.quit();
  return { json: { success: false, message: `Erro: ${error.message}` } };
}

// Tool: clear_cart
const Redis = require('ioredis');
const redis = new Redis($env.REDIS_URL);

const sessionKey = $('Extrai Campos').item.json.session_key;
const cartKey = `vilafood:cart:${sessionKey}`;

try {
  await redis.del(cartKey);
  await redis.quit();

  return { json: { success: true, message: '🗑️ Carrinho limpo! Você pode começar um novo pedido.' } };
} catch (error) {
  await redis.quit();
  return { json: { success: false, message: `Erro: ${error.message}` } };
}
